PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE component_status (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    component_name TEXT NOT NULL,
                    component_type TEXT NOT NULL,
                    status TEXT NOT NULL,
                    response_time_ms INTEGER,
                    error_message TEXT,
                    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE orchid_collection_log (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    source TEXT NOT NULL,
                    records_collected INTEGER,
                    success_rate REAL,
                    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE system_repairs (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    component_name TEXT NOT NULL,
                    repair_action TEXT NOT NULL,
                    success BOOLEAN,
                    timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
                );
CREATE TABLE processing_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    orchid_id INTEGER,
                    correlation_id TEXT,
                    stage TEXT NOT NULL,
                    status TEXT NOT NULL,
                    details JSON,
                    latency_ms INTEGER,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (orchid_id) REFERENCES orchid_record (id)
                );
CREATE TABLE error_events (
                    id INTEGER PRIMARY KEY AUTOINCREMENT,
                    orchid_id INTEGER,
                    correlation_id TEXT,
                    stage TEXT NOT NULL,
                    error_type TEXT NOT NULL,
                    message TEXT NOT NULL,
                    stack TEXT,
                    severity TEXT DEFAULT 'error',
                    suggestion TEXT,
                    resolved BOOLEAN DEFAULT FALSE,
                    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                    FOREIGN KEY (orchid_id) REFERENCES orchid_record (id)
                );
CREATE TABLE processing_metrics_minute (
                    ts TIMESTAMP PRIMARY KEY,
                    processed INTEGER DEFAULT 0,
                    success INTEGER DEFAULT 0,
                    errors INTEGER DEFAULT 0,
                    avg_latency_ms REAL,
                    queue_depth INTEGER DEFAULT 0
                );
DELETE FROM sqlite_sequence;
CREATE INDEX idx_processing_events_orchid ON processing_events(orchid_id);
CREATE INDEX idx_processing_events_correlation ON processing_events(correlation_id);
CREATE INDEX idx_error_events_orchid ON error_events(orchid_id);
CREATE INDEX idx_error_events_type ON error_events(error_type);
COMMIT;
